const moment = require('moment');
test("format", () => {
  const m = moment.utc("2024-01-31T10:05:09.042Z");
  expect(m.format("YYYY-MM-DD HH:mm:ss.SSS")).to.equal("2024-01-31 10:05:09.042");
  expect(m.format("Do MMMM YYYY, dddd, h:mm A")).to.equal("31st January 2024, Wednesday, 10:05 AM");
  expect(m.format()).to.equal("2024-01-31T10:05:09Z");
  expect(m.toISOString()).to.equal("2024-01-31T10:05:09.042Z");
  expect(m.unix()).to.equal(1706695509);
  expect(m.valueOf()).to.equal(1706695509042);
});
test("arithmetic", () => {
  const m = moment.utc("2024-01-31T00:00:00Z");
  expect(m.clone().add(1, "month").format("YYYY-MM-DD")).to.equal("2024-02-29");
  expect(m.clone().subtract(1, "day").format("YYYY-MM-DD")).to.equal("2024-01-30");
  expect(m.clone().add(2, "hours").format("HH:mm")).to.equal("02:00");
  expect(m.clone().endOf("month").format("YYYY-MM-DD HH:mm:ss")).to.equal("2024-01-31 23:59:59");
  expect(m.clone().startOf("year").format("YYYY-MM-DD")).to.equal("2024-01-01");
  expect(moment.utc("2024-03-01").diff(moment.utc("2024-01-31"), "days")).to.equal(30);
  expect(moment.utc("2024-03-01").diff(moment.utc("2024-01-01"), "months")).to.equal(2);
});
test("compare and parse", () => {
  expect(moment.utc("2024-01-01").isBefore(moment.utc("2024-01-02"))).to.be.true;
  expect(moment.utc("2024-01-01T10:00:00Z").isSame(moment.utc("2024-01-01T23:00:00Z"), "day")).to.be.true;
  expect(moment.utc("05/03/2024", "DD/MM/YYYY").format("YYYY-MM-DD")).to.equal("2024-03-05");
  expect(moment.unix(0).utc().format("YYYY")).to.equal("1970");
  expect(moment("not a date").isValid()).to.be.false;
});
